// Example detection logic
function detectResultFormat(result) {
  // Handle null/undefined case
  if (result == null) return { type: 'none', content: null };
  
  // Handle error case
  if (result.isError) return { type: 'error', content: result.error };
  
  // Handle object case
  if (typeof result === 'object') return { type: 'json', content: result };
  
  // Handle string case - could be JSON, text, CSV etc.
  if (typeof result === 'string') {
    try {
      // Try parsing as JSON
      const parsed = JSON.parse(result);
      return { type: 'json', content: parsed };
    } catch (e) {
      // Check if it's CSV (simple detection)
      if (result.includes(',') && result.split('\\n').length > 1) {
        return { type: 'csv', content: result };
      }
      
      // Default to plain text
      return { type: 'text', content: result };
    }
  }
  
  // Fallback
  return { type: 'unknown', content: result };
}

// Then render based on type
function renderParsedResult(parsedResult) {
  switch(parsedResult.type) {
    case 'json': return renderJsonData(parsedResult.content);
    case 'text': return renderTextData(parsedResult.content);
    case 'csv': return renderCsvData(parsedResult.content);
    case 'error': return renderError(parsedResult.content);
    default: return renderUnknownData(parsedResult.content);
  }
}
